# Source-backed narrative translations for CP054, authored per manga/story block.
# Headers are explicit Japanese metadata lines; story is translated as a continuous
# paragraph then split back into the original number of ordered record IDs.
SEGMENTS = [
(747, 767, ["Hiroyuki Takei", "Từ số 31 năm 1998", "Đến số 40 năm 2004"],
 "Shaman King kể về Yoh Asakura, chàng shaman sống ung dung, cứ thuận theo tự nhiên, nhưng ngày càng trưởng thành qua những trận chiến. Một đêm trên đường về từ lớp học thêm, Manta Oyamada, học sinh trường Shinra, gặp một cậu trai ngồi ngắm sao cùng những hồn ma ở nghĩa địa. Hôm sau, cậu trai ấy lại chuyển vào lớp Manta! Đó là Yoh Asakura, shaman có thể nối hai cõi âm dương, trò chuyện và mượn sức mạnh của thần linh, tinh linh. Ở chùa Saigan, Yoh gặp linh hồn samurai Amidamaru từ 600 năm trước. Sau trận đụng độ với Wooden Sword Ryu, cả hai hợp ý và Amidamaru trở thành linh hồn hộ vệ của Yoh. Rồi Yoh bị cuốn vào Shaman Fight, cuộc chiến chọn ra Shaman King. Cậu còn gánh nhiệm vụ đánh bại Hao, tổ tiên nhà Asakura tái sinh thành người anh sinh đôi của mình."),
(768, 788, ["Masaya Tokuhiro", "Từ số 27 năm 1990", "Đến số 18 năm 1995"],
 "Vừa hài vừa hơi người lớn, truyện kể cuộc sống náo nhiệt của Tar-chan, vua rừng bảo vệ muông thú khỏi thợ săn, và Jane, cô vợ từng là siêu mẫu New York, nay tròn trịa và cực kỳ dữ dằn. Bị bỏ rơi tại châu Phi khi còn bé, Tar-chan được cặp tinh tinh Etekichi và Eteko nhặt về nuôi. Chú khỉ đột Gori dạy cậu võ thuật, còn Etekichi thì truyền cả mớ kiến thức hơi nhạy cảm. Lớn lên, Tar-chan thành vua rừng đúng nghĩa. Khi làm hướng dẫn viên, anh cứu Jane khỏi sư tử ngay lúc cô chụp ảnh, rồi cả hai phải lòng nhau. Từ đó là những ngày chẳng bao giờ yên của đôi vợ chồng và bầy thú yêu quý họ. Chiến binh Anabebe của tộc Upopo, nữ sinh viên Helen quyến rũ và học trò Pedro cũng góp mặt, ai cũng có một nét quái chiêu riêng!"),
(789, 808, ["Hirohiko Araki", "Từ số 1–2 năm 1987"],
 "Thiên truyện phiêu lưu kỳ quái của Hirohiko Araki mở ra với Part 1: Phantom Blood, nơi quý tộc Jonathan chiến đấu với Dio, kẻ biến thành ma cà rồng nhờ Stone Mask. Part 2: Battle Tendency là cuộc tử chiến giữa Joseph, cháu Jonathan, các chiến binh Hamon và Pillar Men, những kẻ tạo ra Stone Mask. Part 3: Stardust Crusaders theo chân Jotaro Kujo, cháu Joseph, đến Ai Cập tìm Dio hồi sinh. Part 4: Diamond Is Unbreakable xoay quanh những vụ việc bí ẩn Josuke Higashikata, con ngoài giá thú của Joseph, gặp ở Morioh. Part 5: Golden Wind kể về Giorno Giovanna, con trai Dio, trên đường thành Gang-Star. Part 6: Stone Ocean đưa Jolyne, con gái Jotaro, vào ác mộng nhà tù. Part 7: Steel Ball Run mở ra một thế giới mới cùng cuộc đua xuyên Bắc Mỹ. Và cuộc phiêu lưu vẫn tiếp tục!"),
(809, 829, ["Takehiko Inoue", "Từ số 42 năm 1990", "Đến số 27 năm 1996"],
 "Bộ manga bóng rổ đình đám vẫn được yêu mến đến tận bây giờ. 'Cậu thích bóng rổ chứ?' Chỉ một câu của Haruko Akagi đã đổi đời Hanamichi Sakuragi, cậu học sinh cá biệt bị các cô gái từ chối hết lần này đến lần khác. Vì muốn gần Haruko, Hanamichi gia nhập đội bóng trường Shohoku, nơi toàn cá tính khó đỡ. Đội trưởng Takenori Akagi từng khổ sở vì thiếu đồng đội giỏi; Hisashi Mitsui là xạ thủ MVP cấp hai từng bỏ bóng rổ vì chấn thương gối trái; Ryota Miyagi tuy nhỏ con nhưng có tốc độ khiến đối thủ xoay như chong chóng; Kaede Rukawa là tân binh thiên tài đủ sức chi phối cả trận đấu. Dưới sự dìu dắt của thầy Anzai, Hanamichi cùng cả đội nhắm tới giải toàn quốc. Qua mỗi trận, cậu tìm được nơi mình tỏa sáng, tiến bộ thần tốc dù mới nhập môn và trưởng thành thành cứu tinh thật sự của đội!"),
(830, 850, ["Masami Kurumada", "Từ số 1–2 năm 1986", "Đến số 49 năm 1990"],
 "Khi cái ác tràn lan, những chiến binh của hy vọng sẽ xuất hiện. Đó là các Athena's Saints, những thiếu niên huyền thoại đến mức thần thoại Hy Lạp cũng chẳng ghi tên. Seiya mồ côi được Graude Foundation nuôi dưỡng, đưa đến Hy Lạp rèn luyện để trở thành Saint. Sau khi giành được Pegasus Cloth, cậu trở lại Nhật Bản với mong ước gặp chị gái. Nhưng thay vì đoàn tụ, Seiya phải bước vào chuỗi chiến đấu bất tận với tư cách Saint của Athena. Lấy cảm hứng từ thần thoại Hy Lạp, truyện ca ngợi tình bạn cháy bỏng của những chàng trai. Những bộ Cloth mô phỏng các chòm sao và các chiêu Special Attack hoành tráng từng khiến độc giả mê mẩn. Người hâm mộ đông đảo không chỉ ở Nhật Bản mà còn trên khắp thế giới, đặc biệt là Pháp, nơi bộ truyện được cho là cực kỳ nổi tiếng."),
(851, 870, ["Daimon", "Từ số 34 năm 2005"],
 "Hoàng tử biến thái Taizo Moteo đến từ Makai, thế giới nằm giữa ảo tưởng và hiện thực, chỉ muốn được con gái mê. Thế là những chuyện đời nhảm nhí của cậu biến thành một thiên truyện hài nhại đủ thứ, tự xưng là saga về 'tình yêu'. Taizo, nam sinh với cái đầu nhìn đã thấy lạ, chuyển đến trường trung học tư thục Dokidoki Academy. Cậu ta thực chất là hoàng tử Makai. Không may biết được bí mật ấy, học sinh cá biệt Hirotaka Akutsu từ đó bước vào chuỗi ngày kỳ quặc đầy bất hạnh. Bị ép ký khế ước triệu hồi, Hirotaka thành người có thể bị gọi ra qua Asterisk Gate ngay sau mông Taizo, rồi bất đắc dĩ tiếp tay xây 'Taizo Harem Land'. Liệu Taizo có tìm được bảy Dragon Girls, tương truyền tụ họp đủ sẽ ban bất kỳ điều ước nào, để biến giấc mộng harem thành hiện thực?"),
(871, 890, ["Takeshi Konomi", "Từ số 32 năm 1999"],
 "Thiên tài tennis Ryoma Echizen và bạn bè ở đội tennis trường Seigaku trưởng thành qua vô vàn thử thách. Từng vô địch bốn giải trẻ liên tiếp tại Mỹ, Ryoma vào câu lạc bộ của Seishun Academy, ngôi trường lừng danh về tennis. Dù mới học năm nhất, cậu được đặc cách dự vòng xếp hạng nội bộ để tranh suất chính thức. Hạ hai đàn anh, Ryoma thành tay vợt năm nhất đầu tiên được chọn vào đội tuyển chính và góp mặt ở giải khu vực. Seigaku vượt qua loạt sự cố để giành vé dự giải Tokyo. Sau giải, đội trưởng Tezuka đề nghị đấu với Ryoma. Tezuka thắng, nhưng đã khích lệ cậu: 'Hãy trở thành trụ cột của Seigaku!' Thất bại ấy thổi bùng khát vọng mạnh hơn của Ryoma. Seigaku tiếp tục thắng giải Tokyo, rồi Kanto và tiến thẳng tới giải toàn quốc!"),
(891, 910, ["Katsura Hoshino", "Từ số 27 năm 2004"],
 "Bối cảnh là một thế kỷ XIX giả tưởng. Vũ khí Akuma được tạo từ bi kịch của người sống, linh hồn người chết và máy móc, rồi tấn công nhân loại. Chỉ những chiến binh được chọn gọi là Exorcist mới có thể tiêu diệt chúng. Truyện theo chân Allen Walker và cuộc chiến dữ dội giữa các Exorcist với Millennium Earl, kẻ chế tạo Akuma để đưa thế giới đến tận thế. Mọi chuyện bắt đầu khoảng một thế kỷ trước, khi người ta tìm thấy một chiếc hộp đá chứa lời tiên tri hủy diệt từ nền văn minh cổ, cùng cách dùng Innocence, vật chất mang sức mạnh của thần. Người tạo hộp đã đánh bại Millennium Earl, nhưng đại hồng thủy Noah nhấn chìm thế giới và khiến Innocence tản mát. Để ngăn tận thế tái diễn, Exorcist được Innocence lựa chọn tiếp tục chiến đấu. Allen, người mang thánh giá trên tay trái, cũng bị cuốn vào cuộc chiến ấy."),
(911, 932, ["Tsugumi Ohba (kịch bản)", "Takeshi Obata (tranh)", "Từ số 1 năm 2004<IDEOSP>", "Đến số 24 năm 2006"],
 "Một thiên trinh thám căng não giữa thiên tài trẻ tuổi sở hữu quyển sổ của tử thần và những người quyết bắt hắn. Light Yagami là học sinh trung học đứng đầu cả nước, nhưng cuộc sống khiến cậu phát chán. Một ngày, cậu nhặt được cuốn sổ Death Note. Chỉ cần viết tên ai đó trong lúc hình dung gương mặt, người ấy sẽ chết. Light dùng nó liên tiếp xử lý các tội phạm nguy hiểm. Thế gian gọi kẻ giết người vô hình ấy là Kira; thậm chí có người tung hô hắn như vị cứu tinh. Nhưng không phải ai cũng chấp nhận việc tự ý tước đoạt mạng sống. Một người đứng lên bắt Kira: L, thám tử bí ẩn chẳng ai biết tên thật, diện mạo hay nơi ở, nhưng được đồn giải được mọi vụ án. Trận đấu trí giữa Light và L vì Death Note chính thức bắt đầu!"),
(933, 952, ["Akira Toriyama", "Từ số 5–6 năm 1980", "Đến số 39 năm 1984"],
 "Penguin Village là ngôi làng quê mùa nằm trên đảo Gengoro. Tại đó, nhà khoa học thiên tài tự phong Senbei Norimaki chế tạo robot hình người Arale, mở màn cho loạt chuyện hài ấm áp cùng dân làng quái chiêu. Vì làm gì cũng hỏng, Senbei bị gọi là Dr. Slump. Một ngày, ông chế tạo thành công Arale và đưa cô bé đến trường cấp hai, giả làm em gái của mình. Khổ nỗi, sức mạnh của Arale chẳng tuân theo lẽ thường, khiến cả làng náo loạn. Rồi những nhân vật khó quên lần lượt xuất hiện: Gatchan, em bé có cánh ăn được mọi thứ trừ cao su; Obotchaman, robot tương tự Arale do nhà khoa học phản diện Dr. Mashirito chế tạo. Mỗi người góp thêm một màn náo động, khiến làng Penguin chẳng có ngày nào bình yên!"),
(953, 973, ["Hiroshi Gamo", "Từ số 35 năm 1993", "Đến số 30 năm 1997"],
 "Truyện hài về một cậu nhóc vô tình thành anh hùng và cuộc chiến cùng đồng đội. Mùa hè năm 1993, vụ nổ lớn giữa vũ trụ khiến những người ngoài hành tinh hung ác mất quê nhà và hướng về Trái Đất. Lucky Man, siêu anh hùng chẳng mạnh mẽ gì nhưng may mắn số một vũ trụ, đến bảo vệ hành tinh. Trong khi ấy, Yoichi Tsuitenai, cậu học sinh xui xẻo nhất Nhật Bản, lại trải qua một sáng đen đủi như thường lệ. Đã vậy còn bị phi thuyền rơi trúng, chết ngay tại chỗ! Khi hồn cậu sắp bay lên trời, Lucky Man đuổi theo phi thuyền và xuất hiện. Để hoạt động trên Trái Đất, Lucky Man đề nghị cứu mạng Yoichi để đổi lấy việc mượn cơ thể cậu. Yoichi đồng ý ngay, cả hai hợp nhất. Thế là những ngày chiến đấu của Yoichi trong hình hài Lucky Man chính thức bắt đầu!"),
(974, 993, ["Từ số 51 năm 1984", "Đến số 25 năm 1995"],
 "Truyền thuyết kể rằng ai thu thập đủ bảy Dragon Balls có thể được ban bất cứ điều ước nào. Cuộc đời Son Goku, cậu bé sống sâu trong núi, thay đổi hoàn toàn khi gặp Bulma, cô nàng tự nhận vừa xinh vừa là thiên tài phát minh, và biết đến Dragon Balls. Goku lớn lên qua các chuyến phiêu lưu tìm ngọc, thời gian tu luyện cùng Master Roshi và những trận đấu với đối thủ đáng gờm. Cậu đánh bại King Piccolo muốn thống trị thế giới rồi cả con trai hắn là Piccolo Jr. Sau đó, Goku và bạn bè còn đối mặt Vegeta, hoàng tử Saiyan đến từ vũ trụ; Frieza trên hành tinh Namek quê Piccolo; Cell, người máy sinh học do Dr. Gero của Red Ribbon Army tạo ra; và Majin Buu được phù thủy Babidi hồi sinh. Qua những trận chiến ngày càng khốc liệt, cả nhóm đã nhiều lần cứu lấy thế giới!"),
]
SEGMENTS += [
(994, 1011, ["Masashi Kishimoto", "Từ số 43 năm 1999"],
 "Truyện ninja đầy những trận đấu dữ dội kể về Naruto, cậu bé mang Cửu Vĩ bị phong ấn trong người, và hành trình trưởng thành. Khoảng hai năm rưỡi sau khi kế hoạch đưa Sasuke rời Orochimaru trở về thất bại, Naruto hoàn tất chuyến tu luyện cùng Jiraiya, một trong Legendary Sannin, rồi trở lại làng Lá. Đúng lúc ấy, Gaara, người đã lên làm Kazekage của làng Cát, bị tổ chức bí ẩn Akatsuki bắt cóc. Akatsuki quy tụ những ninja khét tiếng đã rời bỏ các làng, trong đó có Itachi, anh ruột Sasuke; ngay cả Orochimaru cũng từng là thành viên. Nhận lời cầu cứu gửi tới Konoha, Naruto cùng Sakura lên đường trong đội Kakashi. Akatsuki, Orochimaru và nhóm Naruto: cuộc chiến ba bên giờ đây chính thức bùng nổ!"),
(1012, 1031, ["Koji Kiriyama", "Từ số 26 năm 1993", "Đến số 30 năm 1994"],
 "Ninku là câu chuyện hành động ninja về Fusuke, cựu đội trưởng đội số 1 của tổ chức võ thuật Ninku, và những đồng đội giữ vững lý tưởng hòa bình sau chiến tranh. Tổ chức này từng sát cánh cùng mười hai thủ lĩnh gọi là Eto Nin, chiến đấu trong thời Chiến Quốc để kết thúc loạn lạc. Năm mươi năm trước, thế giới lại bước vào một thời kỳ nội chiến. Đội quân Ninku nổi tiếng bất khả chiến bại đã giúp thống nhất thiên hạ ba năm trước, mở ra kỷ nguyên EDO. Tưởng rằng hòa bình đã đến, nào ngờ tiếng kêu của dân bị áp bức vẫn vang khắp nơi. Ninku Wolf, lực lượng do các cựu thành viên lập ra, đang âm thầm mưu đồ thống trị thế giới bằng Ninku. Fusuke cùng Toji, cựu đội trưởng đội số 6, và Aira của đội số 10 lao vào cuộc chiến Ninku lần thứ hai!"),
(1032, 1051, ["Yoshihiro Togashi", "Từ số 14 năm 1998"],
 "Có những kẻ bị ma lực của hai chữ 'chưa biết' mê hoặc, và người ta gọi họ là Hunter. Gon cũng mơ trở thành Hunter như cha mình, Ging. Nghe kể về nghề của cha, cậu quyết theo con đường ấy. Trong kỳ thi Hunter, Gon gặp Leorio, Kurapika, Killua và cả ảo thuật gia Hisoka. Cùng nhau vượt qua thử thách, cuối cùng Gon cũng đỗ kỳ thi nổi tiếng khó nhằn. Nhưng gian nan thật sự chỉ mới bắt đầu! Tạm biệt Leorio và Kurapika, Gon cùng Killua đến Heavens Arena kiếm tiền đi đường. Ở đây cả hai biết đến Nen và phải vất vả mới làm chủ được. Sau khi về Whale Island, Gon biết đến Greed Island, trò chơi do Ging tạo ra, rồi vào thế giới game cùng Killua. Tuy không tìm được manh mối về cha, năng lực Nen của Gon đã mạnh hơn rất nhiều. Và hành trình tiếp tục hướng tới NGL!"),
(1052, 1071, ["Kyosuke Usuta", "Từ số 38 năm 2000"],
 "Một bộ truyện hài phi lý hết nước chấm, kể về Piyohiko, cậu trai luôn bị đời đẩy đi đâu thì đi đó, và Jaguar, gã thổi sáo ngang ngược chẳng ai trị nổi. Tất cả nhân vật đều bị cuốn vào chuỗi sinh hoạt hỗn loạn của hai người. Piyohiko, tên thật Kiyohiko Sakeru, mới 17 tuổi và mơ làm nhạc sĩ guitar. Một hôm, cậu lấy hết can đảm đi dự buổi tuyển chọn, rồi gặp một gã thổi sáo bí hiểm. Gã đó chính là Jaguar, người kéo Piyohiko vào đời hài bất đắc dĩ! Piyohiko gia nhập Garikson Pro để theo nghề nhạc. Jaguar lại thế chỗ Hammer, giảng viên hip-hop, rồi tự mở khoa Sáo. Piyohiko vừa học thổi sáo vừa sống chung ký túc với Jaguar. Còn Hammer nhường lớp, lên gác mái tu luyện. Sau đó thêm cô gái mơ làm idol Takana nhập hội; khoa Sáo giờ có tổng cộng năm thành viên."),
(1072, 1092, ["Nobuhiro Watsuki", "Từ số 30 năm 2003", "Đến số 21–22 năm 2005"],
 "Kakugane là hợp kim siêu nhiên do thuật giả kim tinh luyện, kích hoạt bởi bản năng người sử dụng. Bản năng sinh tồn giúp tăng hồi phục, còn ý chí chiến đấu tạo nên một vũ khí có một không hai. Chiến binh giả kim Tokiko dùng chính mình làm mồi nhử để dụ Homunculus, quái vật ăn thịt người, ra mặt. Chứng kiến cảnh đó, học sinh Kazuki Muto lao tới cứu cô nhưng bị đâm xuyên tim. Tokiko trao Kakugane cho Kazuki, cứu mạng cậu. Phản ứng với bản năng chiến đấu của Kazuki, Kakugane hóa thành ngọn giáo xung kích, hạ gục Homunculus. Kazuki quyết sát cánh cùng Tokiko. Sau khi đánh bại Koshaku Chono, kẻ tạo ra Homunculus, và thuộc hạ của hắn, cả hai nhận nhiệm vụ mới từ đội trưởng: tìm hiểu, triệt phá 'chiến binh phản bội' hồi sinh bằng kỹ thuật Homunculus và liên minh siêu nhân ưu tú đang muốn tôn hắn làm vua."),
(1093, 1113, ["Kentaro Yabuki", "Từ số 32 năm 2000", "Đến số 29 năm 2004"],
 "Chronos là tổ chức khổng lồ nắm một phần ba kinh tế thế giới. Train Heartnet, sát thủ huyền thoại thuộc đội tinh nhuệ Numbers, mang súng đen và hình xăm số XIII, được biết đến như điềm gở mang tên Black Cat. Người ta tưởng Train đã bị xử tử vì phản bội Chronos. Nhưng hai năm sau, anh vẫn tự do như mèo hoang, kiếm sống bằng nghề thợ săn tiền thưởng 'Sweeper' cùng Sven. Anh cũng tìm kẻ giết người bạn thân Saya Minatsuki. Hung thủ là Creed, đồng đội cũ của Train thời ở Chronos. Một ngày, Creed dẫn Apostles of the Stars xuất hiện trước mặt Train, rủ anh cùng làm cách mạng, nghiền nát Chronos và thanh lọc thế giới. Train cự tuyệt. Vì ám ảnh muốn chiếm Train làm của riêng, Creed dùng đủ thủ đoạn ép anh về phe mình. Thế là cuộc chiến dữ dội giữa Chronos, Apostles of the Stars và đồng đội của Train bắt đầu!"),
(1114, 1133, ["Tite Kubo", "Từ số 36–37 năm 2001"],
 "Bleach là truyện hành động về tình bạn và những Shinigami chiến đấu bằng sức mạnh đặc biệt vì con người lẫn linh hồn. Ichigo Kurosaki vốn nhìn thấy ma, rồi gặp Rukia Kuchiki, cô gái tự xưng là Shinigami. Để bảo vệ gia đình khỏi Hollow, quái vật nuốt linh hồn, Ichigo vô tình lấy sức mạnh Shinigami của Rukia. Cậu phải thay cô làm Shinigami đại diện. Nhưng chuyển sức mạnh cho người sống là trọng tội. Rukia bị đưa về Soul Society và kết án tử hình. Ichigo cùng bạn bè ở thế giới người sống và Soul Society xông vào cứu cô. Họ chiến đấu với các đội viên, đội trưởng của Gotei 13, đôi khi lại nhận chính sự giúp đỡ của họ. Cuối cùng Rukia được giải cứu. Tuy nhiên, lợi dụng tình trạng hỗn loạn, đội trưởng Đội 5 Sosuke Aizen đảo chính và cướp Hogyoku, một vật chất cực kỳ nguy hiểm."),
(1134, 1153, ["Ryu Fujisaki", "Từ số 28 năm 1996", "Đến số 47 năm 2000"],
 "Lấy bối cảnh Trung Hoa cổ đại, Hoshin Engi là truyện giả tưởng nơi người phàm, tiên nhân và yêu quái tranh đấu xoay quanh kế hoạch bí ẩn Hoshin Project. Để tiêu diệt Daji, nữ yêu tiên thao túng vua nhà Ân và dân chúng, Yuanshi Tianzun của núi Kunlun giao đệ tử Taikobo thực hiện kế hoạch. Taikobo đi khắp nơi chiêu mộ đồng đội. Mưu trí và tính cách của cậu thu hút rất nhiều bạn hữu mạnh mẽ. Nhưng Daji cũng bày mưu, xúi những yêu tiên ở đảo Kingo đánh nhau với phe Taikobo. Cuộc xung đột dần cuốn cả nhân giới lẫn tiên giới vào cuộc cách mạng Ân–Chu. Giữa chiến tranh, một thế lực bí hiểm thao túng lịch sử từ bóng tối lộ diện, mang tên 'Cột mốc lịch sử'. Rốt cuộc thế lực ấy là ai, mục đích thật sự của Hoshin Project là gì, Taikobo là ai và Daji thực sự muốn điều gì...?"),
(1154, 1175, ["Buronson (kịch bản)", "Tetsuo Hara (tranh)", "Từ số 41 năm 1983", "Đến số 35 năm 1988"],
 "Năm 199X, thế giới chìm trong biển lửa hạt nhân, nhưng loài người vẫn sống sót. Nước và thức ăn khan hiếm, kẻ mạnh dùng bạo lực áp bức kẻ yếu. Kenshiro, người kế thừa Hokuto Shinken, môn ám sát quyền thuật chỉ truyền cho một người, lang bạt và giao chiến với nhiều cường địch. Anh đối đầu các truyền nhân Nanto Seiken, rồi tới Raoh, đại huynh từng cùng học Hokuto Shinken. Sau trận tử chiến, Kenshiro đánh bại Raoh tự xưng Ken-Oh và biến mất vào hoang mạc cùng người yêu Yuria đang mang bệnh. Hòa bình chẳng kéo dài: đế quốc Thiên Đế bắt đầu áp bức dân. Kenshiro hạ tổng đốc tàn ác Jakoh, nhưng Lin lại bị bắt cóc. Truy đuổi cô đến vùng đất Shura, anh phát hiện đó là quê hương, cũng là nơi Hokuto ra đời. Đánh bại Kaioh, cao thủ mạnh nhất của Hokuto Ryuken, Kenshiro tiếp tục lên đường sau khi chứng kiến Ryu, con trai Raoh và người kế thừa được chọn, trưởng thành."),
(1176, 1195, ["Yoshio Sawai", "Từ số 12 năm 2001"],
 "Năm 300X, Trái Đất nằm dưới ách thống trị của Đế quốc Maruhage. Hoàng đế Tsuru Tsururina IV coi đầu trọc là biểu tượng quyền lực nên ra lệnh 'săn tóc' trên toàn thế giới, bắt mọi người cạo đầu. Đội Hair Hunt chuyên trách chuyện ấy; thế lực đế quốc hùng mạnh đến nỗi không nước nào dám chống. Người dân khốn khổ vì những màn săn tóc vô lý. Giữa thời ấy, một người đàn ông đứng lên bảo vệ tự do mái tóc và hòa bình: Bobobo-bo Bo-bobo! Để đánh bại Maruhage rồi cả Neo Maruhage, Bobobo cứ thế băng băng tiến về đâu đó, không ai rõ. Gặp cao thủ Shinken nào cản đường, anh cũng quật ngã, thậm chí còn lôi về làm đồng minh. Chặng đường tiếp tục với những người bạn đáng tin, gắn bó qua chiến đấu... trừ vài ngoại lệ! Nói họ có chịu chơi không ư? Chơi tất, sợ gì!"),
(1196, 1215, ["Yusei Matsui", "Từ số 12 năm 2005"],
 "Một bộ truyện trinh thám kỳ dị về Neuro Nogami, ma nhân sống bằng năng lượng giải phóng khi phá giải 'bí ẩn', và Yako Katsuragi, nữ sinh trung học bị hắn dựng thành thám tử lừng danh để che giấu thân phận. Sau khi ăn sạch mọi bí ẩn ở Ma giới, Neuro lên mặt đất săn thêm món mới. Hắn nhắm tới Yako, cô gái có cha chết bí ẩn. Nếu Yako trở nên nổi tiếng với danh thám tử, những vụ án hóc búa chắc chắn sẽ tự tìm đến! Thế là Yako bị ép làm thám tử tư khi còn đi học; 'trợ lý' Neuro ngoài mặt giúp đỡ, thực chất liên tục dọa nạt cô và lôi cô vào vụ kỳ án. Dần dần, Yako hứng thú với nội tâm con người. Rồi một kẻ địch vượt xa hiểu biết nhân loại xuất hiện: siêu trộm X (Sai). Với trí tuệ siêu phàm cùng 777 năng lực Ma giới, hãy giải sạch, hay đúng hơn là ăn sạch mọi bí ẩn!"),
(1216, 1230, ["Tsunomaru", "Từ số 50 năm 1994", "Đến số 9 năm 1998<IDEOSP>"],
 "Một chú ngựa thuần chủng bé tẹo, chỉ nặng 100 kg, đối đầu hàng loạt đối thủ trong bộ truyện đua ngựa vừa nhiệt huyết vừa lầy lội. Trang trại Midori đang túng thiếu, kỳ vọng ngựa mẹ Midoriko sinh ra cứu tinh. Nào ngờ chú ngựa con lông trắng vừa bé vừa có mặt giống hà mã! Thế nhưng chú sớm phô diễn đôi chân phi thường khi kéo lê cả Midoriko nặng 500 kg. Sau đó chú có cuộc gặp định mệnh với chuột Chubei, bạn đồng hành trong những cuộc đua, đau lòng chia tay mẹ, rồi gặp đối thủ số một Cascade và tay đua Kansuke Yamamoto. Ngay trước ngày ra mắt, chú ngựa được đặt tên Midori Makibao."),
]
